            <h3 style="color: var(--danger); margin-bottom: 0.5rem;">Query Error</h3>
            <p style="font-size: 0.9rem; color: #fca5a5;">${err.message}</p>
          </div>
        `;
      } finally {
        submitBtn.disabled = false;
        submitBtn.innerHTML = '<span>Query Meal Plan</span>';
      }
