    function renderTabContent() {
      if (!currentResponseData) return;

      if (activeTab === 'recipes') {
        renderRecipes(currentResponseData.recommendations || []);
      } else if (activeTab === 'shopping') {
        renderShopping(currentResponseData.shoppingList);
      } else if (activeTab === 'raw') {
        renderRaw(currentResponseData);
      }
    }

    function renderRecipes(recipes) {
      if (recipes.length === 0) {
        displayArea.innerHTML = `
          <div class="empty-state">
            <h3>No matching recipes found</h3>
            <p>Try loosening restrictions or adjusting filters.</p>
          </div>
        `;
        return;
      }

      let html = '<div class="recommendations-list">';

      recipes.forEach((item, idx) => {
        const recipe = item.recipe || {};
        const tags = item.matchedTags || [];
        const labelChecks = item.labelCheck || [];

        const tagsHtml = tags.map(t => `<span class="tag-chip">${escapeHtml(t)}</span>`).join('');
        const safetyChip = item.allergySafety && item.allergySafety.status === 'safe'
          ? `<span class="tag-chip allergy-safe">🛡️ ${escapeHtml(item.allergySafety.status)}</span>`
          : `<span class="tag-chip" style="background: rgba(239, 68, 68, 0.2); color: #f87171;">⚠️ ${escapeHtml(item.allergySafety?.status || 'check')}</span>`;

        const prepTime = recipe.prepMinutes ? `⏱️ ${recipe.prepMinutes} mins` : '';
        const servings = recipe.servings ? `👥 ${recipe.servings} servings` : '';

        // Ingredients
        const ingredientsHtml = (recipe.ingredients || []).map(ing => {
          const qty = ing.quantity ? `${ing.quantity} ${ing.unit || ''}` : '';
          return `<li><span>${escapeHtml(ing.name || ing.rawText)}</span><span style="color: var(--text-muted); font-family: monospace;">${escapeHtml(qty)}</span></li>`;
        }).join('');

        // Steps
        const stepsHtml = (recipe.steps || []).map(s => `<li>${escapeHtml(s)}</li>`).join('');

        // Label check notice
        let labelCheckNotice = '';
        if (labelChecks.length > 0) {
          labelCheckNotice = `
            <div class="label-check-box">
              <strong>Allergen check recommended:</strong> ${escapeHtml(labelChecks.join(', '))}
            </div>
          `;
        }

        html += `
          <div class="recipe-card">
            <div class="recipe-header">
              <div>
                <h3 class="recipe-title">
                  <a href="${escapeHtml(item.url)}" target="_blank" rel="noopener noreferrer">
                    ${escapeHtml(item.title)} ↗
                  </a>
                </h3>
                <div class="recipe-channel">
                  Channel: <strong>${escapeHtml(item.channel || 'YouTube')}</strong>
                  ${prepTime ? ` • ${prepTime}` : ''}
                  ${servings ? ` • ${servings}` : ''}
                </div>
              </div>
            </div>

            <div class="recipe-meta-tags">
              ${safetyChip}
              ${tagsHtml}
            </div>

            ${item.whyItFits ? `
              <div class="why-it-fits">
                <strong>Why it fits:</strong> ${escapeHtml(item.whyItFits)}
              </div>
            ` : ''}

            ${item.healthNotes ? `
              <div class="health-notes">
                <strong>Health Notes:</strong> ${escapeHtml(item.healthNotes)}
              </div>
            ` : ''}

            ${labelCheckNotice}

            <details>
              <summary>
                <span>View Ingredients (${(recipe.ingredients || []).length}) & Preparation Steps</span>
                <span>▼</span>
              </summary>
              <div class="details-content">
                <div>
                  <h4 style="font-size: 0.85rem; margin-bottom: 0.5rem; color: var(--accent);">Ingredients</h4>
                  <ul class="ingredients-list">
                    ${ingredientsHtml}
                  </ul>
                </div>
                <div>
                  <h4 style="font-size: 0.85rem; margin-bottom: 0.5rem; color: var(--accent);">Preparation Steps</h4>
                  <ol class="steps-list">
                    ${stepsHtml}
                  </ol>
                </div>
              </div>
            </details>
          </div>
        `;
      });

      html += '</div>';
      displayArea.innerHTML = html;
    }

    function renderShopping(shoppingList) {
      if (!shoppingList || !shoppingList.sections) {
        displayArea.innerHTML = `
          <div class="empty-state">
            <h3>No shopping list generated</h3>
          </div>
        `;
        return;
      }

      let html = '<div class="shopping-container">';

      if (shoppingList.warnings && shoppingList.warnings.length > 0) {
        html += `
          <div class="disclaimer-banner" style="background: rgba(56, 189, 248, 0.08); border-color: rgba(56, 189, 248, 0.25); color: #bae6fd;">
            <span>ℹ️</span>
            <div>${shoppingList.warnings.map(w => escapeHtml(w)).join('<br>')}</div>
          </div>
        `;
      }

      html += '<div class="shopping-grid">';

      (shoppingList.sections || []).forEach(sec => {
        if (!sec.items || sec.items.length === 0) return;
        html += `
          <div class="shopping-section">
            <div class="section-title">📦 ${escapeHtml(sec.section)}</div>
            ${sec.items.map(item => `
              <div class="shopping-item">
                <span>${escapeHtml(item.name)}</span>
                <span class="qty">${item.amount ? `${item.amount} ${item.unit || ''}` : (item.note || 'as needed')}</span>
              </div>
            `).join('')}
          </div>
        `;
      });

      if (shoppingList.pantry && shoppingList.pantry.length > 0) {
        html += `
          <div class="shopping-section" style="border-style: dashed;">
            <div class="section-title" style="color: var(--safe-text);">🧂 Pantry Staples (Check Supply)</div>
            ${shoppingList.pantry.map(item => `
              <div class="shopping-item">
                <span>${escapeHtml(item.name)}</span>
                <span class="qty">${item.amount ? `${item.amount} ${item.unit || ''}` : (item.note || 'check')}</span>
              </div>
            `).join('')}
          </div>
        `;
      }

      html += '</div></div>';
      displayArea.innerHTML = html;
    }

    function renderRaw(data) {
      displayArea.innerHTML = `
        <pre class="raw-json-box"><code>${escapeHtml(JSON.stringify(data, null, 2))}</code></pre>
      `;
    }

    function escapeHtml(str) {
      if (!str) return '';
      return String(str)
        .replace(/&/g, '&amp;')
        .replace(/</g, '&lt;')
        .replace(/>/g, '&gt;')
        .replace(/"/g, '&quot;')
        .replace(/'/g, '&#039;');
    }
  </script>
</body>
</html>
